// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title ChainSignatures
/// @author Relay Protocol
/// @notice Library for encoding JSON requests for chain signatures
library ChainSignatures {
  /// @notice Encodes a JSON request for the signer
  /// @param payloadString The hex string representation of the payload to sign
  /// @param curve The curve to use for signing
  /// @param domainId The domain ID
  /// @return The encoded JSON request
  function encodeJSONRequest(
    string memory payloadString,
    string memory curve,
    string memory signerPath,
    string memory domainId
  ) public pure returns (bytes memory) {
    return
      abi.encodePacked(
        // solhint-disable-next-line quotes
        '{"request":{"payload_v2": { "',
        curve,
        // solhint-disable-next-line quotes
        '":"',
        payloadString,
        // solhint-disable-next-line quotes
        '"},"path":"',
        signerPath,
        // solhint-disable-next-line quotes
        '","domain_id":',
        domainId,
        // solhint-disable-next-line quotes
        "}}"
      );
  }

  /// @notice Converts bytes data to its hex string representation
  /// @param data The bytes data to convert (arbitrary length)
  /// @return The hex string representation of the data
  function stringifyBytes(
    bytes memory data
  ) public pure returns (string memory) {
    bytes16 alphabet = 0x30313233343536373839616263646566; // "0123456789abcdef"
    bytes memory str = new bytes(data.length * 2);
    for (uint256 i = 0; i < data.length; ) {
      uint8 b = uint8(data[i]);
      // precompute offset
      uint256 offset = i << 1; // i * 2
      str[offset] = alphabet[b >> 4]; // high nibble
      str[offset + 1] = alphabet[b & 0x0f]; // low nibble
      unchecked {
        i++;
      }
    }
    return string(str);
  }
}

contracts/Config.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title IRelayAllocatorOwner
/// @author Relay Protocol
/// @notice Minimal interface for reading the allocator owner
interface IRelayAllocatorOwner {
  /// @notice Returns the current owner of the allocator contract
  /// @return account Owner address
  function owner() external view returns (address account);
}

/// @title Config
/// @author Relay Protocol
/// @notice Bytes32 to bytes32 configuration store managed by the RelayAllocator owner
contract Config {
  /// @notice RelayAllocator contract whose owner administers this config
  address public immutable ALLOCATOR;

  /// @notice Mapping of config keys to stored values
  mapping(bytes32 => bytes32) private values;

  /// @notice Tracks whether a config key has been explicitly set
  mapping(bytes32 => bool) private valueExists;

  /// @notice Emitted when the allocator is set
  /// @param allocator RelayAllocator contract address
  event AllocatorSet(address indexed allocator);

  /// @notice Emitted when a config value is set
  /// @param key Config key
  /// @param value Config value
  event ValueSet(bytes32 indexed key, bytes32 value);

  /// @notice Thrown when a caller is not the current allocator owner
  /// @param account Caller address
  error CallerIsNotAllocatorOwner(address account);

  /// @notice Thrown when attempting to read a config key that has not been set
  /// @param key Config key
  error ConfigValueNotSet(bytes32 key);

  /// @notice Thrown when batch input arrays do not have the same length
  /// @param keysLength Number of keys provided
  /// @param valuesLength Number of values provided
  error ArrayLengthMismatch(uint256 keysLength, uint256 valuesLength);

  /// @notice Creates a new config store
  /// @param _allocator RelayAllocator contract address
  constructor(address _allocator) {
    ALLOCATOR = _allocator;
    emit AllocatorSet(_allocator);
  }

  /// @notice Restricts access to the current owner of the allocator contract
  modifier onlyAllocatorOwner() {
    if (msg.sender != IRelayAllocatorOwner(ALLOCATOR).owner()) {
      revert CallerIsNotAllocatorOwner(msg.sender);
    }
    _;
  }

  /// @notice Sets a config value for a key
  /// @param key Config key
  /// @param value Config value
  function setValue(bytes32 key, bytes32 value) external onlyAllocatorOwner {
    values[key] = value;
    valueExists[key] = true;
    emit ValueSet(key, value);
  }

  /// @notice Sets multiple config values
  /// @param keys Config keys
  /// @param newValues Config values
  function setValues(
    bytes32[] calldata keys,
    bytes32[] calldata newValues
  ) external onlyAllocatorOwner {
    if (keys.length != newValues.length) {
      revert ArrayLengthMismatch(keys.length, newValues.length);
    }

    for (uint256 i; i < keys.length; ++i) {
      values[keys[i]] = newValues[i];
      valueExists[keys[i]] = true;
      emit ValueSet(keys[i], newValues[i]);
    }
  }

  /// @notice Returns a config value for a key and reverts if it is not set
  /// @param key Config key
  /// @return value Config value
  function getValue(bytes32 key) external view returns (bytes32 value) {
    if (!valueExists[key]) {
      revert ConfigValueNotSet(key);
    }

    return values[key];
  }
}

contracts/ERC20View.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// @title IHub
/// @author Relay Protocol
/// @notice Interface for the Hub contract
interface IHub {
  /// @notice Returns the balance of a token for an owner
  /// @param owner The owner address
  /// @param id The token ID
  /// @return The balance amount
  function balanceOf(address owner, uint256 id) external view returns (uint256);

  /// @notice Transfers tokens from one address to another
  /// @param sender The sender address
  /// @param receiver The receiver address
  /// @param id The token ID
  /// @param amount The amount to transfer
  /// @return True if successful
  function transferFrom(
    address sender,
    address receiver,
    uint256 id,
    uint256 amount
  ) external returns (bool);

  /// @notice Returns the total supply of a token
  /// @param id The token ID
  /// @return The total supply
  function totalSupply(uint256 id) external view returns (uint256);

  /// @notice Returns the name of a token
  /// @param id The token ID
  /// @return The token name
  function name(uint256 id) external view returns (string memory);

  /// @notice Returns the symbol of a token
  /// @param id The token ID
  /// @return The token symbol
  function symbol(uint256 id) external view returns (string memory);

  /// @notice Returns the decimals of a token
  /// @param id The token ID
  /// @return The token decimals
  function decimals(uint256 id) external view returns (uint8);

  /// @notice Returns the token URI of a token
  /// @param id The token ID
  /// @return The token URI
  function tokenURI(uint256 id) external view returns (string memory);

  /// @notice Returns the allowance of a spender for an owner
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param id The token ID
  /// @return The allowance amount
  function allowance(
    address owner,
    address spender,
    uint256 id
  ) external view returns (uint256);

  /// @notice Approves a spender to spend tokens on behalf of owner
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param id The token ID
  /// @param amount The amount to approve
  /// @return True if successful
  function approveFor(
    address owner,
    address spender,
    uint256 id,
    uint256 amount
  ) external returns (bool);
}

/// @title ERC20View
/// @author Relay Protocol
/// @notice ERC20-compatible view contract that interfaces with the Hub
contract ERC20View {
  /*//////////////////////////////////////////////////////////////
                                EVENTS
    //////////////////////////////////////////////////////////////*/

  /// @notice Emitted when an approval is made
  event Approval(address indexed owner, address indexed spender, uint256 value);
  /// @notice Emitted when a transfer occurs
  event Transfer(address indexed from, address indexed to, uint256 value);

  /*//////////////////////////////////////////////////////////////
                            CUSTOM ERRORS
    //////////////////////////////////////////////////////////////*/

  error ERC20ViewInsufficientAllowance(
    address spender,
    uint256 allowance,
    uint256 needed
  );

  /*//////////////////////////////////////////////////////////////
                                STORAGE
    //////////////////////////////////////////////////////////////*/

  /// @notice The Hub contract instance
  IHub public immutable hub;
  /// @notice The token ID this view represents
  uint256 public immutable tokenId;

  /*//////////////////////////////////////////////////////////////
                              CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

  /// @notice Constructor for ERC20View
  /// @param _tokenId The token ID this view represents
  constructor(uint256 _tokenId) {
    hub = IHub(msg.sender);
    tokenId = _tokenId;
  }

  /*//////////////////////////////////////////////////////////////
                          ERC20 IMPLEMENTATION
    //////////////////////////////////////////////////////////////*/

  /// @notice Returns the name of the token
  /// @return The token name
  function name() public view returns (string memory) {
    return hub.name(tokenId);
  }

  /// @notice Returns the symbol of the token
  /// @return The token symbol
  function symbol() public view returns (string memory) {
    return hub.symbol(tokenId);
  }

  /// @notice Returns the decimals of the token
  /// @return The token decimals
  function decimals() public view returns (uint8) {
    return hub.decimals(tokenId);
  }

  /// @notice Returns the token URI
  /// @return The token URI
  function tokenURI() public view returns (string memory) {
    return hub.tokenURI(tokenId);
  }

  /// @notice Returns the total supply of the token
  /// @return The total supply
  function totalSupply() public view returns (uint256) {
    return hub.totalSupply(tokenId);
  }

  /// @notice Returns the balance of an account
  /// @param account The account address
  /// @return The balance amount
  function balanceOf(address account) public view returns (uint256) {
    return hub.balanceOf(account, tokenId);
  }

  /// @notice Returns the allowance amount for a spender
  /// @param owner The owner address
  /// @param spender The spender address
  /// @return The allowance amount
  function allowance(
    address owner,
    address spender
  ) public view returns (uint256) {
    return hub.allowance(owner, spender, tokenId);
  }

  /// @notice Approves a spender to spend tokens
  /// @param spender The spender address
  /// @param value The amount to approve
  /// @return True if successful
  function approve(address spender, uint256 value) public returns (bool) {
    bool success = hub.approveFor(msg.sender, spender, tokenId, value);
    if (success) {
      emit Approval(msg.sender, spender, value);
    }
    return success;
  }

  /// @notice Transfers tokens to another address
  /// @param to The recipient address
  /// @param value The amount to transfer
  /// @return True if successful
  function transfer(address to, uint256 value) public returns (bool) {
    bool success = hub.transferFrom(msg.sender, to, tokenId, value);
    if (success) {
      emit Transfer(msg.sender, to, value);
    }
    return success;
  }

  /// @notice Transfers tokens from one address to another
  /// @param from The sender address
  /// @param to The recipient address
  /// @param value The amount to transfer
  /// @return True if successful
  function transferFrom(
    address from,
    address to,
    uint256 value
  ) public returns (bool) {
    // Check allowance unless the spender is the owner
    if (msg.sender != from) {
      uint256 currentAllowance = hub.allowance(from, msg.sender, tokenId);
      if (currentAllowance < type(uint256).max) {
        if (currentAllowance < value) {
          revert ERC20ViewInsufficientAllowance(
            msg.sender,
            currentAllowance,
            value
          );
        }
        // slither-disable-next-line unused-return
        hub.approveFor(from, msg.sender, tokenId, currentAllowance - value);
      }
    }

    // Execute the transfer on the Hub
    bool success = hub.transferFrom(from, to, tokenId, value);
    if (success) {
      emit Transfer(from, to, value);
    }
    return success;
  }

  /*//////////////////////////////////////////////////////////////
                          HUB EVENT EMISSION
    //////////////////////////////////////////////////////////////*/

  /// @notice Emits a transfer event (only callable by the hub)
  /// @param from The sender address
  /// @param to The recipient address
  /// @param value The amount transferred
  function emitTransferEvent(address from, address to, uint256 value) external {
    if (msg.sender == address(hub)) {
      emit Transfer(from, to, value);
    }
  }

  /// @notice Emits an approval event (only callable by the hub)
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param value The approved amount
  function emitApprovalEvent(
    address owner,
    address spender,
    uint256 value
  ) external {
    if (msg.sender == address(hub)) {
      emit Approval(owner, spender, value);
    }
  }
}

