pragma solidity ^0.8.28;

import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

import {RelayHub} from "./RelayHub.sol";
import {Utils} from "./Utils.sol";

/// @notice Parameters passed to a payload builder for constructing a withdrawal payload
struct BuildPayloadParams {
  bytes currency; /// @notice Encoded currency address
  uint256 amount; /// @notice Amount to withdraw
  bytes receiver; /// @notice Encoded receiver address
  uint256 nonce; /// @notice Request nonce
  bytes data; /// @notice Additional payload builder data
}

/// @title IPayloadBuilder
/// @author Relay Protocol
/// @notice Interface for payload builders that create withdrawal payloads for different chains
interface IPayloadBuilder {
  /// @notice Builds a withdrawal payload for the specified parameters
  /// @param chainId The destination chain id
  /// @param depository The depository address
  /// @param params Payload builder parameters
  /// @return payload The built payload
  function buildPayload(
    string calldata chainId,
    bytes calldata depository,
    BuildPayloadParams calldata params
  ) external view returns (bytes memory payload);

  /// @notice Returns an array of hashes that need to be signed for the payload
  /// @param chainId The destination chain id
  /// @param depository The depository address
  /// @param payload The corresponding payload
  /// @return hashes Array of hashes to be signed
  function hashesToSign(
    string calldata chainId,
    bytes calldata depository,
    bytes calldata payload
  ) external view returns (bytes32[] memory hashes);

  /// @notice Returns the curve used for signing
  /// @return name The curve name
  function curve() external pure returns (string memory name);

  /// @notice Returns the family of the payload builder
  /// @return name The family name
  function family() external pure returns (string memory name);
}

/// @title RelayAllocator
/// @author Relay Protocol
/// @notice Manages cross-chain withdrawal requests and payload signing
contract RelayAllocator is Ownable, EIP712 {
  using ECDSA for bytes32;

  /// --- Fields ---

  /// @notice The signing domain for EIP-712 receiver-authorized withdrawals
  string public constant SIGNING_DOMAIN = "RelayAllocator";

  /// @notice The signature version for EIP-712 receiver-authorized withdrawals
  string public constant SIGNATURE_VERSION = "1";

  /// @notice The type hash for WithdrawRequest receiver signatures
  bytes32 public constant PAYLOAD_TYPEHASH =
    keccak256(
      "WithdrawRequest(string chainId,bytes depository,bytes currency,uint256 amount,string spenderChainId,bytes spender,bytes receiver,bytes data,bytes32 nonce)"
    );

  /// @notice Address of the hub contract
  address public immutable HUB;

  /// @notice Mapping of payload builders: chain id => depository => payload builder address
  mapping(string => mapping(bytes => address)) public payloadBuilders;

  /// @notice Unsigned payloads: withdrawal request hash => payload
  mapping(bytes32 => bytes) public payloads;

  /// @notice Signed payloads: withdrawal request hash => hash index => hash to be signed
  mapping(bytes32 => mapping(uint256 => bytes32)) public hashesToSign;

  /// @notice Used nonces for replay protection: signer => nonce => whether it has been used
  mapping(address => mapping(bytes32 => bool)) public usedNonces;

  /// @notice Emitted when the hub contract is set
  /// @param hub Hub contract address
  event HubSet(address indexed hub);

  // --- Events ---

  /// @notice Emitted when a payload builder is set for a chain and depository
  /// @param chainId Chain id
  /// @param depository Encoded depository address
  /// @param builder Payload builder address
  event PayloadBuilderSet(
    string indexed chainId,
    bytes indexed depository,
    address indexed builder
  );

  /// @notice Emitted when a payload is built
  /// @param withdrawRequestHash Withdrawal request hash
  /// @param payload Encoded withdrawal payload
  /// @param hashesToSign Hashes that must be signed for the payload
  event PayloadBuilt(
    bytes32 indexed withdrawRequestHash,
    bytes payload,
    bytes32[] hashesToSign
  );

  // --- Errors ---

  /// @notice Thrown when the caller is neither the spender nor an approved operator
  /// @param account Caller address
  error CallerIsNotApproved(address account);

  /// @notice Thrown when no payload builder is configured for a chain and depository pair
  /// @param chainId Chain id
  /// @param depository Encoded depository address
  error NoPayloadBuilder(string chainId, bytes depository);

  /// @notice Thrown when a withdrawal request hash has already been processed
  /// @param withdrawRequestHash Withdrawal request hash
  error WithdrawRequestAlreadyProcessed(bytes32 withdrawRequestHash);

  /// @notice Thrown when burning funds in the hub unexpectedly returns false
  /// @param from Spender alias whose balance was targeted
  /// @param tokenId Token id burned from the hub
  /// @param amount Amount attempted to burn
  error WithdrawRequestTransferFailed(
    address from,
    uint256 tokenId,
    uint256 amount
  );

  // --- Structs ---

  /// @notice Parameters for a withdrawal request
  struct WithdrawRequest {
    string chainId; /// @notice Chain id of the withdrawal chain
    bytes depository; /// @notice Encoded address of the depository on the withdrawal chain
    bytes currency; /// @notice Encoded address of the currency to be withdrawn
    uint256 amount; /// @notice Amount to withdraw
    string spenderChainId; /// @notice Chain id of the spender
    bytes spender; /// @notice Encoded address of the spender
    bytes receiver; /// @notice Encoded address of the receiver of the withdrawn funds
    bytes data; /// @notice Additional data to be passed to the payload builder
    bytes32 nonce; /// @notice Nonce for replay protection
  }

  /// @notice Creates a new RelayAllocator contract
  /// @param _owner Owner of the contract
  /// @param _hub Hub contract address
  constructor(
    address _owner,
    address _hub
  ) Ownable(_owner) EIP712(SIGNING_DOMAIN, SIGNATURE_VERSION) {
    HUB = _hub;
    emit HubSet(_hub);
  }

  /// @notice Sets or updates the payload builder for a specific chain and depository
  /// @param chainId Chain id
  /// @param depository Encoded depository address
  /// @param builder Address of the payload builder contract
  function setPayloadBuilder(
    string calldata chainId,
    bytes calldata depository,
    address builder
  ) external onlyOwner {
    payloadBuilders[chainId][depository] = builder;
    emit PayloadBuilderSet(chainId, depository, builder);
  }

  /// @notice Submits a withdraw request to the payload builder
  /// @param params The withdraw request parameters
  /// @return withdrawRequestHash The hash of the withdrawal request
  function submitWithdrawRequest(
    WithdrawRequest calldata params
  ) public returns (bytes32 withdrawRequestHash) {
    return _submitWithdrawRequest(params, bytes(""));
  }

  /// @notice Submits a withdraw request using a receiver signature when the spender is the receiver alias
  /// @param params The withdraw request parameters
  /// @param signature EIP-712 signature produced by the receiver
  /// @return withdrawRequestHash The hash of the withdrawal request
  function submitWithdrawRequestWithSignature(
    WithdrawRequest calldata params,
    bytes calldata signature
  ) public returns (bytes32 withdrawRequestHash) {
    return _submitWithdrawRequest(params, signature);
  }

  /// @notice Internal implementation shared by signed and unsigned withdrawal submissions
  /// @param params The withdraw request parameters
  /// @param signature Optional receiver signature
  /// @return withdrawRequestHash The hash of the withdrawal request
  function _submitWithdrawRequest(
    WithdrawRequest calldata params,
    bytes memory signature
  ) internal returns (bytes32 withdrawRequestHash) {
    // Check if the payload builder is set
    address builder = payloadBuilders[params.chainId][params.depository];
    if (builder == address(0)) {
      revert NoPayloadBuilder(params.chainId, params.depository);
    }

    address spenderAlias = Utils.generateAddress(
      params.spenderChainId,
      params.spender
    );

    bool callerIsSpender = params.spender.length == 20 &&
      address(bytes20(params.spender)) == msg.sender;

    // Only the spender itself, an operator, or the spender via signature can trigger withdrawals
    if (
      !callerIsSpender &&
      !RelayHub(HUB).isOperator(spenderAlias, msg.sender) &&
      !consumeSpenderSignature(params, signature)
    ) {
      revert CallerIsNotApproved(msg.sender);
    }

    // Build payload
    bytes memory payload = _buildPayload(builder, params);

    // Ensure the request wasn't already processed
    withdrawRequestHash = keccak256(abi.encode(params));
    if (payloads[withdrawRequestHash].length > 0) {
      revert WithdrawRequestAlreadyProcessed(withdrawRequestHash);
    }

    // Mark the request as processed
    payloads[withdrawRequestHash] = payload;

    // Burn the funds from the spender. RelayHub.burn currently either reverts or returns true,
    // so the false branch below is retained only as a defensive guard against future hub changes.
    uint256 tokenId = Utils.generateTokenId(params.chainId, params.currency);
    bool result = RelayHub(HUB).burn(spenderAlias, tokenId, params.amount);
    if (!result) {
      revert WithdrawRequestTransferFailed(
        spenderAlias,
        tokenId,
        params.amount
      );
    }

    // Store the hashes to be signed in contract storage
    bytes32[] memory _hashesToSign = IPayloadBuilder(builder).hashesToSign(
      params.chainId,
      params.depository,
      payload
    );
    for (uint256 i; i < _hashesToSign.length; ++i) {
      hashesToSign[withdrawRequestHash][i] = _hashesToSign[i];
    }

    emit PayloadBuilt(withdrawRequestHash, payload, _hashesToSign);
  }

  /// @notice Verifies and consumes a spender signature for a withdrawal request
  /// @dev Signature-based authorization is only available for 20-byte EVM spenders.
  /// @param params The withdrawal request parameters
  /// @param signature The signature to verify
  /// @return matched True if the signature matches the spender and the nonce was unused
  function consumeSpenderSignature(
    WithdrawRequest calldata params,
    bytes memory signature
  ) internal returns (bool matched) {
    if (signature.length == 0 || params.spender.length != 20) {
      return false;
    }

    address signer = address(bytes20(params.spender));
    if (usedNonces[signer][params.nonce]) {
      return false;
    }

    bytes32 digest = _hashTypedDataV4(
      keccak256(
        abi.encode(
          PAYLOAD_TYPEHASH,
          keccak256(bytes(params.chainId)),
          keccak256(params.depository),
          keccak256(params.currency),
          params.amount,
          keccak256(bytes(params.spenderChainId)),
          keccak256(params.spender),
          keccak256(params.receiver),
          keccak256(params.data),
          params.nonce
        )
      )
    );

    (address recovered, ECDSA.RecoverError recoverError, ) = ECDSA.tryRecover(
      digest,
      signature
    );
    if (recoverError != ECDSA.RecoverError.NoError || recovered != signer) {
      return false;
    }

    usedNonces[signer][params.nonce] = true;
    return true;
  }

  /// @notice Builds a payload using the configured builder for the given request
  /// @param builder Payload builder address
  /// @param params Withdrawal request parameters
  /// @return payload Encoded withdrawal payload
  function _buildPayload(
    address builder,
    WithdrawRequest calldata params
  ) internal view returns (bytes memory payload) {
    return
      IPayloadBuilder(builder).buildPayload(
        params.chainId,
        params.depository,
        BuildPayloadParams({
          currency: params.currency,
          amount: params.amount,
          receiver: params.receiver,
          nonce: uint256(params.nonce),
          data: params.data
        })
      );
  }
}
","keccak256":"0x62fec3536bf51cfb5718c41f43a18e0dc85f7de2a5e242b02415ebcb93473a32","license":"MIT"},"contracts/RelayHub.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/utils/Strings.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "./ERC20View.sol";

/// @title IERC20View
/// @author Relay Protocol
/// @notice Interface for ERC20View contract
interface IERC20View {
  /// @notice Emits a transfer event
  /// @param from The sender address
  /// @param to The recipient address
  /// @param value The amount transferred
  function emitTransferEvent(address from, address to, uint256 value) external;

  /// @notice Emits an approval event
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param value The approved amount
  function emitApprovalEvent(
    address owner,
    address spender,
    uint256 value
  ) external;
}

/// @title RelayHub
/// @author Relay Protocol
/// @notice Based on Solmate standard ERC6909 implementation. (https://github.com/transmissions11/solmate/blob/main/src/tokens/ERC6909.sol)
contract RelayHub is AccessControl, EIP712 {
  using Strings for uint256;

  /*//////////////////////////////////////////////////////////////
                            CUSTOM ERRORS
    //////////////////////////////////////////////////////////////*/

  /// @notice Error thrown when non-ERC20View tries to call approveFor
  /// @param caller The address that attempted to call approveFor
  /// @param expectedERC20View The expected ERC20View address for the token
  error OnlyERC20ViewCanCallApproveFor(
    address caller,
    address expectedERC20View
  );

  /// @notice Error thrown when permit deadline has expired
  error PermitDeadlineExpired();

  /// @notice Error thrown when permit signature is invalid
  error InvalidPermitSignature();

  /// @notice Error thrown when permit owner is the zero address
  error InvalidPermitOwner();

  /*//////////////////////////////////////////////////////////////
                                 EVENTS
    //////////////////////////////////////////////////////////////*/

  /// @notice Emitted when an operator is set for an owner
  event OperatorSet(
    address indexed owner,
    address indexed operator,
    bool approved
  );

  /// @notice Emitted when an approval is made
  event Approval(
    address indexed owner,
    address indexed spender,
    uint256 indexed id,
    uint256 amount
  );

  /// @notice Emitted when a transfer occurs
  event Transfer(
    address caller,
    address indexed from,
    address indexed to,
    uint256 indexed id,
    uint256 amount
  );

  struct TokenMetadata {
    string name;
    string symbol;
    uint8 decimals;
    string originFamily;
    uint256 originChainId;
    string originAsset;
  }

  /*//////////////////////////////////////////////////////////////
                             ERC6909 STORAGE
    //////////////////////////////////////////////////////////////*/

  mapping(address => mapping(address => bool)) internal _isOperator;

  /// @notice Mapping of owner to token ID to balance
  mapping(address => mapping(uint256 => uint256)) public balanceOf;

  /// @notice Mapping of owner to spender to token ID to allowance
  mapping(address => mapping(address => mapping(uint256 => uint256)))
    public allowance;

  /// @notice Mapping of token ID to total supply
  mapping(uint256 => uint256) public totalSupply;

  /// @notice Mapping of owner to nonce for permit signatures
  mapping(address => uint256) public nonces;

  /*//////////////////////////////////////////////////////////////
                          ERC20VIEW STORAGE
    //////////////////////////////////////////////////////////////*/

  // tokenId => ERC20View address
  /// @notice Mapping of token ID to ERC20View contract address
  mapping(uint256 => address) public erc20Views;

  /*//////////////////////////////////////////////////////////////
                        ERC20VIEW EVENTS
    //////////////////////////////////////////////////////////////*/

  /// @notice Emitted when an ERC20View is created
  event ERC20ViewCreated(uint256 indexed tokenId, address indexed erc20View);
  /// @notice Mapping of token ID to token metadata
  mapping(uint256 => TokenMetadata) public tokenMetadata;

  /// @notice Contract URI for metadata
  string public contractURI = "";

  /*//////////////////////////////////////////////////////////////
                             ROLES
    //////////////////////////////////////////////////////////////*/

  /// @notice Role for operators
  bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
  /// @notice Role for editors
  bytes32 public constant EDITOR_ROLE = keccak256("EDITOR_ROLE");
  /// @notice Role for administrators
  bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");

  /*//////////////////////////////////////////////////////////////
                          EIP712 CONSTANTS
    //////////////////////////////////////////////////////////////*/

  /// @notice EIP712 typehash for permit
  bytes32 public constant PERMIT_TYPEHASH =
    keccak256(
      "Permit(address owner,address spender,uint256 tokenId,uint256 value,uint256 nonce,uint256 deadline)"
    );

  /*//////////////////////////////////////////////////////////////
                             CONSTRUCTOR
    //////////////////////////////////////////////////////////////*/

  /// @notice Constructor for RelayHub contract
  /// @param adminAddress The address to grant admin role
  constructor(address adminAddress) EIP712("RelayHub", "1") {
    _setRoleAdmin(OPERATOR_ROLE, ADMIN_ROLE);
    _setRoleAdmin(EDITOR_ROLE, ADMIN_ROLE);
    _setRoleAdmin(ADMIN_ROLE, ADMIN_ROLE);
    _grantRole(ADMIN_ROLE, adminAddress);
  }

  /*//////////////////////////////////////////////////////////////
                              ERC6909 LOGIC
    //////////////////////////////////////////////////////////////*/

  /// @notice Checks if an address is an operator for an account
  /// @param account The account address
  /// @param operator The operator address
  /// @return True if the operator is authorized
  function isOperator(
    address account,
    address operator
  ) public view returns (bool) {
    return hasRole(OPERATOR_ROLE, operator) || _isOperator[account][operator];
  }

  /// @notice Internal function to set an operator for an account
  /// @param account The account address
  /// @param operator The operator address
  /// @param approved Whether to approve the operator
  /// @return result True if successful
  function _setOperatorFor(
    address account,
    address operator,
    bool approved
  ) internal returns (bool result) {
    _isOperator[account][operator] = approved;
    emit OperatorSet(account, operator, approved);
    return true;
  }

  /// @notice Sets an operator for an account (only callable by OPERATOR_ROLE)
  /// @param account The account address
  /// @param operator The operator address
  /// @param approved Whether to approve the operator
  /// @return result True if successful
  function setOperatorFor(
    address account,
    address operator,
    bool approved
  ) public onlyRole(OPERATOR_ROLE) returns (bool result) {
    return _setOperatorFor(account, operator, approved);
  }

  /// @notice Sets an operator for the caller
  /// @param operator The operator address
  /// @param approved Whether to approve the operator
  /// @return result True if successful
  function setOperator(
    address operator,
    bool approved
  ) public returns (bool result) {
    return _setOperatorFor(msg.sender, operator, approved);
  }

  /// @notice Transfers tokens to another address
  /// @param receiver The recipient address
  /// @param id The token ID
  /// @param amount The amount to transfer
  /// @return result True if successful
  function transfer(
    address receiver,
    uint256 id,
    uint256 amount
  ) public returns (bool result) {
    balanceOf[msg.sender][id] -= amount;

    balanceOf[receiver][id] += amount;

    emit Transfer(msg.sender, msg.sender, receiver, id, amount);
    _emitERC20ViewEvent(id, msg.sender, receiver, amount);

    return true;
  }

  /// @notice Transfers tokens from one address to another
  /// @param sender The sender address
  /// @param receiver The recipient address
  /// @param id The token ID
  /// @param amount The amount to transfer
  /// @return result True if successful
  function transferFrom(
    address sender,
    address receiver,
    uint256 id,
    uint256 amount
  ) public returns (bool result) {
    if (
      msg.sender != sender &&
      !isOperator(sender, msg.sender) &&
      erc20Views[id] != msg.sender
    ) {
      uint256 allowed = allowance[sender][msg.sender][id];
      if (allowed != type(uint256).max)
        allowance[sender][msg.sender][id] = allowed - amount;
    }

    balanceOf[sender][id] -= amount;

    balanceOf[receiver][id] += amount;

    emit Transfer(msg.sender, sender, receiver, id, amount);
    _emitERC20ViewEvent(id, sender, receiver, amount);

    return true;
  }

  /// @notice Approves a spender to spend tokens
  /// @param spender The spender address
  /// @param id The token ID
  /// @param amount The amount to approve
  /// @return result True if successful
  function approve(
    address spender,
    uint256 id,
    uint256 amount
  ) public returns (bool result) {
    allowance[msg.sender][spender][id] = amount;

    emit Approval(msg.sender, spender, id, amount);
    _emitERC20ViewApprovalEvent(id, msg.sender, spender, amount);

    return true;
  }

  /// @notice Approves a spender to spend tokens on behalf of owner (only callable by ERC20View)
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param id The token ID
  /// @param amount The amount to approve
  /// @return result True if successful
  function approveFor(
    address owner,
    address spender,
    uint256 id,
    uint256 amount
  ) public returns (bool result) {
    if (erc20Views[id] != msg.sender) {
      revert OnlyERC20ViewCanCallApproveFor(msg.sender, erc20Views[id]);
    }

    allowance[owner][spender][id] = amount;

    emit Approval(owner, spender, id, amount);
    // Note: The ERC20View will emit its own Approval event

    return true;
  }

  /// @notice Permits a spender to spend tokens via signature (EIP712)
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param tokenId The token ID
  /// @param value The allowance amount
  /// @param deadline The deadline timestamp
  /// @param v The recovery byte of the signature
  /// @param r Half of the ECDSA signature pair
  /// @param s Half of the ECDSA signature pair
  function permit(
    address owner,
    address spender,
    uint256 tokenId,
    uint256 value,
    uint256 deadline,
    uint8 v,
    bytes32 r,
    bytes32 s
  ) public {
    if (owner == address(0)) {
      revert InvalidPermitOwner();
    }

    if (block.timestamp > deadline) {
      revert PermitDeadlineExpired();
    }

    uint256 ownerNonce = nonces[owner];

    bytes32 structHash = keccak256(
      abi.encode(
        PERMIT_TYPEHASH,
        owner,
        spender,
        tokenId,
        value,
        ownerNonce,
        deadline
      )
    );

    bytes32 hash = _hashTypedDataV4(structHash);

    address signer = ECDSA.recover(hash, v, r, s);

    if (signer != owner) {
      revert InvalidPermitSignature();
    }

    nonces[owner] = ownerNonce + 1;

    allowance[owner][spender][tokenId] = value;

    emit Approval(owner, spender, tokenId, value);
    _emitERC20ViewApprovalEvent(tokenId, owner, spender, value);
  }

  /// @notice Mints tokens to a receiver (only callable by OPERATOR_ROLE)
  /// @param receiver The recipient address
  /// @param id The token ID
  /// @param amount The amount to mint
  /// @return result True if successful
  function mint(
    address receiver,
    uint256 id,
    uint256 amount
  ) public onlyRole(OPERATOR_ROLE) returns (bool result) {
    _mint(receiver, id, amount);
    return true;
  }

  /// @notice Burns tokens from a sender (only callable by OPERATOR_ROLE)
  /// @param sender The sender address
  /// @param id The token ID
  /// @param amount The amount to burn
  /// @return result True if successful
  function burn(
    address sender,
    uint256 id,
    uint256 amount
  ) public onlyRole(OPERATOR_ROLE) returns (bool result) {
    _burn(sender, id, amount);
    return true;
  }

  /// @notice Sets token metadata (only callable by EDITOR_ROLE)
  /// @param id The token ID
  /// @param metadata The token metadata
  function setTokenMetadata(
    uint256 id,
    TokenMetadata calldata metadata
  ) public onlyRole(EDITOR_ROLE) {
    tokenMetadata[id] = metadata;
  }

  /// @notice Returns the name of a token
  /// @param id The token ID
  /// @return The token name
  function name(uint256 id) public view returns (string memory) {
    return tokenMetadata[id].name;
  }

  /// @notice Returns the symbol of a token
  /// @param id The token ID
  /// @return The token symbol
  function symbol(uint256 id) public view returns (string memory) {
    return tokenMetadata[id].symbol;
  }

  /// @notice Returns the decimals of a token
  /// @param id The token ID
  /// @return The token decimals
  function decimals(uint256 id) public view returns (uint8) {
    if (tokenMetadata[id].decimals == 0) {
      return 18;
    }
    return tokenMetadata[id].decimals;
  }

  /// @notice Sets the contract URI (only callable by EDITOR_ROLE)
  /// @param uri The contract URI
  function setContractURI(string calldata uri) public onlyRole(EDITOR_ROLE) {
    contractURI = uri;
  }

  /// @notice Returns the token URI
  /// @param id The token ID
  /// @return The token URI
  function tokenURI(uint256 id) public view returns (string memory) {
    return string.concat(contractURI, "/", id.toString());
  }

  /*//////////////////////////////////////////////////////////////
                              ERC165 LOGIC
    //////////////////////////////////////////////////////////////*/

  /// @notice Returns the domain separator for EIP712
  /// @return The domain separator
  function DOMAIN_SEPARATOR() external view returns (bytes32) {
    return _domainSeparatorV4();
  }

  /// @notice Checks if the contract supports an interface
  /// @param interfaceId The interface ID to check
  /// @return result True if the interface is supported
  function supportsInterface(
    bytes4 interfaceId
  ) public pure override(AccessControl) returns (bool result) {
    return
      interfaceId == 0x01ffc9a7 || // ERC165 Interface ID for ERC165
      interfaceId == 0x0f632fb3; // ERC165 Interface ID for ERC6909
  }

  /*//////////////////////////////////////////////////////////////
                        INTERNAL MINT/BURN LOGIC
    //////////////////////////////////////////////////////////////*/

  /// @notice Internal function to mint tokens
  /// @param receiver The recipient address
  /// @param id The token ID
  /// @param amount The amount to mint
  function _mint(address receiver, uint256 id, uint256 amount) internal {
    balanceOf[receiver][id] += amount;
    if (totalSupply[id] == 0) {
      _createERC20View(id);
    }
    totalSupply[id] += amount;

    emit Transfer(msg.sender, address(0), receiver, id, amount);
    _emitERC20ViewEvent(id, address(0), receiver, amount);
  }

  /// @notice Internal function to burn tokens
  /// @param sender The sender address
  /// @param id The token ID
  /// @param amount The amount to burn
  function _burn(address sender, uint256 id, uint256 amount) internal {
    balanceOf[sender][id] -= amount;
    totalSupply[id] -= amount;

    emit Transfer(msg.sender, sender, address(0), id, amount);
    _emitERC20ViewEvent(id, sender, address(0), amount);
  }

  /*//////////////////////////////////////////////////////////////
                            INTERNAL HELPERS
  //////////////////////////////////////////////////////////////*/

  /// @notice Internal function to emit ERC20View events
  /// @param id The token ID
  /// @param from The sender address
  /// @param to The recipient address
  /// @param amount The amount transferred
  function _emitERC20ViewEvent(
    uint256 id,
    address from,
    address to,
    uint256 amount
  ) internal {
    address erc20ViewAddress = erc20Views[id];
    if (msg.sender != erc20ViewAddress) {
      IERC20View(erc20ViewAddress).emitTransferEvent(from, to, amount);
    }
  }

  /// @notice Internal function to emit ERC20View approval events
  /// @param id The token ID
  /// @param owner The owner address
  /// @param spender The spender address
  /// @param amount The approved amount
  function _emitERC20ViewApprovalEvent(
    uint256 id,
    address owner,
    address spender,
    uint256 amount
  ) internal {
    address erc20ViewAddress = erc20Views[id];
    if (msg.sender != erc20ViewAddress) {
      IERC20View(erc20ViewAddress).emitApprovalEvent(owner, spender, amount);
    }
  }

  /// @notice Internal function to create an ERC20View contract
  /// @param tokenId The token ID
  /// @return The address of the created ERC20View contract
  function _createERC20View(uint256 tokenId) internal returns (address) {
    if (erc20Views[tokenId] != address(0)) {
      return erc20Views[tokenId];
    }

    ERC20View erc20View = new ERC20View(tokenId);

    address erc20ViewAddress = address(erc20View);
    erc20Views[tokenId] = erc20ViewAddress;

    emit ERC20ViewCreated(tokenId, erc20ViewAddress);
    return erc20ViewAddress;
  }
}
